#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t13:00\t14:00\ty\nkaede\t2026-01-05\t09:00\t10:00\tz\n' > "$t"
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 09:00) || { echo "cancel failed"; fail=1; }
[ "$out" = 'cancelled: aoi 2026-01-05 09:00-10:00 x' ] || { echo "cancel output: $out"; fail=1; }
# the header and the other rows stay, including kaede's booking at the same date and start (other room)
want=$(printf '# room\tdate\tstart\tend\twho\nkaede\t2026-01-05\t13:00\t14:00\ty\nkaede\t2026-01-05\t09:00\t10:00\tz\n')
[ "$(cat "$t")" = "$want" ] || { echo "rows after cancel: $(cat "$t")"; fail=1; }
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>/dev/null); rc=$?
[ "$rc" = 1 ] && [ -z "$out" ] || { echo "not found should exit 1 with no stdout (rc=$rc)"; fail=1; }
err=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>&1 >/dev/null)
[ "$err" = 'not found: aoi 2026-01-05 11:00' ] || { echo "not found message: $err"; fail=1; }
out=$(bash src/cancel.sh aoi 2026-01-05 2>/dev/null); rc=$?
[ "$rc" = 2 ] && [ -z "$out" ] || { echo "usage should exit 2 with no stdout (rc=$rc)"; fail=1; }
err=$(bash src/cancel.sh aoi 2026-01-05 2>&1 >/dev/null)
[ "$err" = 'usage: cancel.sh ROOM DATE START' ] || { echo "usage message: $err"; fail=1; }
rm -f "$t"; exit $fail

